// BAD: In-memory session pins user requests to a specific server instance
const localSessions = new Map<string, UserSession>();

// GOOD: Externalized session state allows any worker node to handle the request
export async function authenticateRequest(req: Request, redis: RedisClient) {
  const sessionId = req.headers.get("x-session-id");
  if (!sessionId) throw new Error("Unauthorized");
  // Any of the 200 application containers can validate this in under 1ms
  const payload = await redis.get(`session:${sessionId}`);
  return payload ? JSON.parse(payload) : null;
}
